// @param float _Seed = 7 [0 .. 100]
// @param float _Width = 0.008 [0.002 .. 0.025]
// @param float _Jaggedness = 0.13 [0 .. 0.25]
// @param float _ForkSpread = 0.22 [0 .. 0.35]
// @param color _Tint = (0.18, 0.48, 1, 1)

float BoltHash(float n)
{
    return frac(sin(n * 127.1 + _Seed * 31.7) * 43758.5453);
}

float BoltNoise(float y, float frequency)
{
    float p = y * frequency;
    float i = floor(p);
    return lerp(BoltHash(i), BoltHash(i + 1), frac(p)) * 2 - 1;
}

float BoltPath(float y)
{
    return 0.5 + _Jaggedness * (BoltNoise(y, 11) + 0.3 * BoltNoise(y + 2, 29));
}

float4 ApplyFX(float2 uv, float4 color)
{
    float y = uv.y;
    float envelope = smoothstep(0.02, 0.15, y) * (1 - smoothstep(0.86, 0.98, y));
    float width = _Width * (0.25 + 0.75 * envelope);
    float distanceToBolt = abs(uv.x - BoltPath(y));

    float t1 = saturate((y - 0.36) / 0.40);
    float branch1 = BoltPath(y) + _ForkSpread * t1;
    float d1 = abs(uv.x - branch1);
    float mask1 = step(0.36, y) * (1 - smoothstep(0.67, 0.76, y));

    float t2 = saturate((y - 0.57) / 0.28);
    float branch2 = BoltPath(y) - _ForkSpread * t2 * 0.85;
    float d2 = abs(uv.x - branch2);
    float mask2 = step(0.57, y) * (1 - smoothstep(0.77, 0.85, y));

    float aa = max(fwidth(uv.x), 0.0001);
    float core = 1 - smoothstep(width, width + aa, distanceToBolt);
    float fork1 = (1 - smoothstep(width * 0.5, width * 0.5 + aa, d1)) * mask1;
    float fork2 = (1 - smoothstep(width * 0.4, width * 0.4 + aa, d2)) * mask2;
    float filament = max(core, max(fork1, fork2));

    float aura = exp2(-distanceToBolt / max(width * 3, 0.0001));
    aura = max(aura, exp2(-d1 / max(width * 2, 0.0001)) * mask1 * 0.65);
    aura = max(aura, exp2(-d2 / max(width * 2, 0.0001)) * mask2 * 0.5);

    float alpha = saturate(filament + aura * 0.35) * envelope * _Tint.a;
    float3 rgb = lerp(_Tint.rgb, float3(0.92, 0.97, 1), filament);
    return float4(rgb, alpha);
}
